package dev.soulboundqa;
import dev.shadowsovereign.mythic.*;
import dev.shadowsovereign.odyssey.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.levelgen.structure.*;
import net.minecraftforge.gametest.*;
@GameTestHolder("soulboundsiteqa") @PrefixGameTestTemplate(false)
public final class NaturalSiteReviewTest {
 @GameTest(templateNamespace="soulboundsiteqa",template="arena",timeoutTicks=12000) public static void latestDojoGeneratesNaturallyAndGuardianAppearsInsideAuthoredBounds(GameTestHelper h){NativeReviewTests.fixture(h,p->{var w=p.serverLevel();int kind=MythicExpedition.IDS.length-1;var site=MythicSites.sites().stream().filter(s->s.kind()==kind).findFirst().orElseThrow();var holder=w.registryAccess().registryOrThrow(Registries.STRUCTURE).getHolderOrThrow(net.minecraft.resources.ResourceKey.create(Registries.STRUCTURE,site.structure()));p.teleportTo(300000.5,100,300000.5);var found=w.getChunkSource().getGenerator().findNearestMapStructure(w,HolderSet.direct(holder),p.blockPosition(),32,false);h.assertTrue(found!=null,"Newest dojo has a native shared-placement candidate in its proper biome");w.getChunkAt(found.getFirst());StructureStart start=null;for(int y=w.getMinBuildHeight();y<w.getMaxBuildHeight();y++){var candidate=w.structureManager().getStructureAt(found.getFirst().atY(y),holder.value());if(candidate.isValid()){start=candidate;break;}}h.assertTrue(start!=null,"Native generator created actual dojo structure start");var at=MythicSites.altar(start,site);h.assertTrue(at!=null&&start.getBoundingBox().isInside(at),"Authored altar lies inside generated rotated building");var cp=new net.minecraft.world.level.ChunkPos(at);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){w.getChunk(cp.x+x,cp.z+z);w.setChunkForced(cp.x+x,cp.z+z,true);}var groundY=w.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE,at.getX(),at.getZ());h.assertTrue(Math.abs(at.getY()-groundY)<45,"Altar and generated surface stay in a plausible building height range");p.teleportTo(at.getX()+.5,at.getY(),at.getZ()+.5);h.runAfterDelay(60,()->{MythicSites.tick(p);MythicExpedition.start(p,kind);var body=MythicExpedition.body(p,kind);h.assertTrue(body!=null&&body.isAlive(),"Real naturally generated dojo starts newest live guardian");h.assertTrue(startBounds(p,kind,body.blockPosition()),"Guardian stands inside saved authored bounds");for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)w.setChunkForced(cp.x+x,cp.z+z,false);NativeReviewTests.finish(h,p);});});}
 static boolean startBounds(net.minecraft.server.level.ServerPlayer p,int kind,net.minecraft.core.BlockPos at){var n=MythicExpedition.state(p,kind);int[] b=n.getIntArray("NaturalBounds");return b.length==6&&at.getX()>=b[0]&&at.getX()<=b[3]&&at.getZ()>=b[2]&&at.getZ()<=b[5];}
}
